types:
TYPE ST_Pump :
STRUCT
    priority : INT;    
    selection : BOOL;  
    RunComd : BOOL;    
END_STRUCT
END_TYPE

declaration:
FUNCTION_BLOCK FB_MultiPump

VAR_INPUT
    mode : BOOL;   
    start : BOOL;  
    stop : BOOL;   
END_VAR
VAR_IN_OUT
    pumpGroup : ARRAY[1..5] OF ST_Pump;
END_VAR
VAR
    i : INT;
    j : INT;
    rank : INT;      
    prioI : INT;
    prioJ : INT;
    inTop3 : BOOL;
END_VAR

implementation:
IF stop THEN
    FOR i := 1 TO 5 DO
        pumpGroup[i].RunComd := FALSE;
    END_FOR


ELSIF mode THEN

    FOR i := 1 TO 5 DO
        rank := 0;
        prioI := pumpGroup[i].priority;
        FOR j := 1 TO 5 DO
            IF j <> i THEN
                prioJ := pumpGroup[j].priority;
                IF (prioJ > prioI) OR ((prioJ = prioI) AND (j < i)) THEN
                    rank := rank + 1;
                END_IF
            END_IF
        END_FOR
        inTop3 := rank < 3;

        pumpGroup[i].RunComd := start AND inTop3;
    END_FOR

ELSE

    FOR i := 1 TO 5 DO
        pumpGroup[i].RunComd := start AND pumpGroup[i].selection;
    END_FOR
END_IF
